contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 mintAmt, uint256 sendAmt) public {
        require(mintAmt > 0 && sendAmt > 0 && sendAmt <= mintAmt);
        c.mintToken(address(this), mintAmt); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(address(0), sendAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted &&
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == balBefore
        );
    }
    receive() external payable {}
}

