        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 mintAmt, uint256 sendAmt) internal {
        vm.assume(mintAmt > 0 && sendAmt > 0 && sendAmt <= mintAmt);
        try c.mintToken(address(this), mintAmt) {} catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(address(0), sendAmt) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted &&
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == balBefore);
